Definition gfa_M_W (sp : word) (SB c R muser msz sa sn T : Z) : list (Z * Z) :=
  [(rb SB c + muser, rb SB c + muser + msz); (sa, sa + sn); (T + 2792, T + 2800); (T + 2872, T + 2888); (R + 48, R + 56);
   (bv_unsigned sp - 640, bv_unsigned sp)]%Z.

